#!/usr/bin/env node

// Deploy Analysis Script
// Inventories skills, analyzes commits since last tag, and recommends version bump.
// Cross-platform: works on Windows and macOS.
// Usage: node deploy-analyze.mjs [--skills-dir <path>]

import { execSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join, resolve } from "node:path";

const args = process.argv.slice(2);
let skillsDir = "skills";

for (let i = 0; i < args.length; i++) {
  if (args[i] === "--skills-dir" && args[i + 1]) {
    skillsDir = args[i + 1];
    i++;
  }
}

const root = resolve(".");

function run(cmd) {
  try {
    return execSync(cmd, { encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] }).trim();
  } catch {
    return null;
  }
}

// --- Git repository check ---

if (!run("git rev-parse --git-dir")) {
  console.error("ERROR: Not a git repository");
  process.exit(1);
}

// --- Skills inventory ---

const skillsPath = join(root, skillsDir);
const skills = [];

if (existsSync(skillsPath)) {
  for (const entry of readdirSync(skillsPath)) {
    const entryPath = join(skillsPath, entry);
    if (statSync(entryPath).isDirectory() && existsSync(join(entryPath, "SKILL.md"))) {
      skills.push(entry);
    }
  }
}

console.log("=== Skills Inventory ===");
console.log(`Directory: ${skillsDir}/`);
console.log(`Count: ${skills.length}`);
if (skills.length > 0) {
  for (const skill of skills) {
    console.log(`  - ${skill}`);
  }
}
console.log("");

// --- Current version ---

function detectCurrentVersion() {
  const pluginJson = join(root, ".claude-plugin", "plugin.json");
  const packageJson = join(root, "package.json");

  if (existsSync(pluginJson)) {
    try {
      const data = JSON.parse(readFileSync(pluginJson, "utf8"));
      if (data.version) return data.version;
    } catch { /* ignore */ }
  }

  if (existsSync(packageJson)) {
    try {
      const data = JSON.parse(readFileSync(packageJson, "utf8"));
      if (data.version) return data.version;
    } catch { /* ignore */ }
  }

  return "unknown";
}

const currentVersion = detectCurrentVersion();
console.log(`Current version: ${currentVersion}`);

// --- Last tag ---

const lastTag = run("git describe --tags --abbrev=0");

if (!lastTag) {
  console.log("INFO: No previous release tags found (first release)");
  console.log("");
  console.log("Recent commits (last 20):");
  const recentLog = run("git log --oneline -20");
  if (recentLog) console.log(recentLog);
  console.log("");
  console.log("=== Recommendation ===");
  console.log("MINOR bump (first release)");
  process.exit(0);
}

console.log(`Last release tag: ${lastTag}`);

// --- Commit count ---

const commitCountStr = run(`git rev-list "${lastTag}"..HEAD --count`);
const commitCount = parseInt(commitCountStr || "0", 10);

if (commitCount === 0) {
  console.log("INFO: No new commits since last release");
  process.exit(0);
}

console.log(`Commits since last release: ${commitCount}`);
console.log("");

// --- Commit history ---

console.log("=== Commit History ===");
const commitLog = run(`git log "${lastTag}"..HEAD --oneline`);
if (commitLog) console.log(commitLog);
console.log("");

// --- Conventional commit analysis ---

function countPattern(pattern) {
  const subjects = run(`git log "${lastTag}"..HEAD --format="%s"`);
  if (!subjects) return 0;
  const re = new RegExp(pattern, "m");
  return subjects.split("\n").filter((line) => re.test(line)).length;
}

const types = {
  feat: countPattern("^feat(\\(.*\\))?!?:"),
  fix: countPattern("^fix(\\(.*\\))?!?:"),
  refactor: countPattern("^refactor(\\(.*\\))?!?:"),
  docs: countPattern("^docs(\\(.*\\))?!?:"),
  chore: countPattern("^chore(\\(.*\\))?!?:"),
  style: countPattern("^style(\\(.*\\))?!?:"),
  ci: countPattern("^ci(\\(.*\\))?!?:"),
  test: countPattern("^test(\\(.*\\))?!?:"),
};

// Breaking changes: "type!:" suffix
const breakingSuffix = countPattern("^[a-z]+(\\(.*\\))?!:");

// Breaking changes: "BREAKING CHANGE" in commit body
let breakingBody = 0;
const bodies = run(`git log "${lastTag}"..HEAD --format="%b"`);
if (bodies) {
  breakingBody = bodies.split("\n").filter((line) => /^BREAKING CHANGE:/.test(line)).length;
}

const breakingCount = breakingSuffix + breakingBody;

const classified = Object.values(types).reduce((a, b) => a + b, 0);
const other = commitCount - classified;

console.log("=== Change Summary ===");
console.log(`Features:      ${types.feat}`);
console.log(`Fixes:         ${types.fix}`);
console.log(`Refactoring:   ${types.refactor}`);
console.log(`Documentation: ${types.docs}`);
console.log(`Chore:         ${types.chore}`);
console.log(`Style:         ${types.style}`);
console.log(`CI:            ${types.ci}`);
console.log(`Tests:         ${types.test}`);
console.log(`Other:         ${other}`);
console.log(`Breaking:      ${breakingCount}`);
console.log("");

// --- File change stats ---

console.log("=== File Changes ===");
const diffStat = run(`git diff "${lastTag}"..HEAD --stat`);
if (diffStat) console.log(diffStat);
console.log("");

// --- Skills changed since last tag ---

const skillChanges = run(`git diff "${lastTag}"..HEAD --name-only -- "${skillsDir}/"`);
if (skillChanges) {
  const changedSkills = new Set();
  for (const file of skillChanges.split("\n")) {
    const parts = file.split("/");
    if (parts.length >= 2 && parts[0] === skillsDir) {
      changedSkills.add(parts[1]);
    }
  }
  if (changedSkills.size > 0) {
    console.log("=== Skills Changed ===");
    for (const skill of changedSkills) {
      console.log(`  - ${skill}`);
    }
    console.log("");
  }
}

// --- Recommendation ---

console.log("=== Recommendation ===");
if (breakingCount > 0) {
  console.log("MAJOR bump (breaking changes detected)");
} else if (types.feat > 0) {
  console.log("MINOR bump (new features)");
} else {
  console.log("PATCH bump (fixes or refactoring)");
}

#!/usr/bin/env node

// Deploy Execution Script
// Bumps version in surface config files, commits, tags, and deploys to surfaces.
// Supports --dry-run, --bump-only, and --push modes.
// Cross-platform: works on Windows and macOS.
//
// Usage:
//   node deploy-execute.mjs <version> --surfaces <s1,s2,...> [--dry-run] [--bump-only] [--push] [--notes-file <path>]
//
// Surfaces: github, claude-code, vscode, copilot-cli
// Version bumps ALWAYS apply to every detected config file regardless of --surfaces.
// The --surfaces flag controls which deployment actions run (GitHub release, etc.).
// Examples:
//   node deploy-execute.mjs 1.2.0 --surfaces github,claude-code --dry-run
//   node deploy-execute.mjs 1.2.0 --surfaces claude-code,vscode --bump-only
//   node deploy-execute.mjs 1.2.0 --surfaces github,claude-code,vscode,copilot-cli --push
//   node deploy-execute.mjs 1.2.0 --surfaces github --push --notes-file changelog.md

import { execSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";

const VALID_SURFACES = ["github", "claude-code", "vscode", "copilot-cli"];
const root = resolve(".");

// --- Parse arguments ---

const args = process.argv.slice(2);
let version = null;
let surfaces = [];
let dryRun = false;
let bumpOnly = false;
let pushMode = false;
let notesFile = null;

for (let i = 0; i < args.length; i++) {
  if (args[i] === "--surfaces" && args[i + 1]) {
    surfaces = args[i + 1].split(",").map((s) => s.trim().toLowerCase());
    i++;
  } else if (args[i] === "--dry-run") {
    dryRun = true;
  } else if (args[i] === "--bump-only") {
    bumpOnly = true;
  } else if (args[i] === "--push") {
    pushMode = true;
  } else if (args[i] === "--notes-file" && args[i + 1]) {
    notesFile = args[i + 1];
    i++;
  } else if (!args[i].startsWith("--") && !version) {
    version = args[i];
  }
}

// --- Validate arguments ---

if (!version) {
  console.error("ERROR: Version argument required");
  console.error("Usage: deploy-execute.mjs <version> --surfaces <s1,s2,...> [--dry-run] [--bump-only] [--push]");
  console.error("Example: deploy-execute.mjs 1.2.0 --surfaces github,claude-code --dry-run");
  process.exit(1);
}

if (!/^\d+\.\d+\.\d+$/.test(version)) {
  console.error(`ERROR: Invalid version format: ${version}`);
  console.error("Expected: X.Y.Z (e.g., 1.2.0)");
  process.exit(1);
}

if (surfaces.length === 0) {
  console.error("ERROR: At least one surface required (--surfaces github,claude-code,vscode,copilot-cli)");
  process.exit(1);
}

for (const s of surfaces) {
  if (!VALID_SURFACES.includes(s)) {
    console.error(`ERROR: Unknown surface '${s}'. Valid: ${VALID_SURFACES.join(", ")}`);
    process.exit(1);
  }
}

const tagName = `v${version}`;
const modeLabel = dryRun ? "DRY RUN" : bumpOnly ? "BUMP ONLY" : pushMode ? "PUSH" : "EXECUTE";

function run(cmd) {
  try {
    return execSync(cmd, { encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] }).trim();
  } catch (e) {
    return null;
  }
}

function runOrFail(cmd) {
  try {
    return execSync(cmd, { encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] }).trim();
  } catch (e) {
    console.error(`ERROR: Command failed: ${cmd}`);
    if (e.stderr) console.error(e.stderr.toString());
    process.exit(1);
  }
}

function logAction(action) {
  const prefix = dryRun ? "[DRY RUN]" : "[EXECUTE]";
  console.log(`${prefix} ${action}`);
}

// --- Git checks ---

if (!run("git rev-parse --git-dir")) {
  console.error("ERROR: Not a git repository");
  process.exit(1);
}

// Check if tag already exists
const existingTags = run("git tag -l") || "";
if (existingTags.split("\n").includes(tagName)) {
  console.error(`ERROR: Tag ${tagName} already exists`);
  process.exit(1);
}

console.log(`=== Deploy ${modeLabel}: v${version} ===`);
console.log(`Surfaces: ${surfaces.join(", ")}`);
console.log("");

// --- Collect ALL config files to update ---
// Version bumps always apply to every detected config file regardless of --surfaces.
// This ensures versions stay in sync across all surfaces. The --surfaces flag only
// controls which deployment actions run in --push mode.

const updates = [];

function readJsonSafe(filePath) {
  try {
    return JSON.parse(readFileSync(filePath, "utf8"));
  } catch {
    return null;
  }
}

function writeJsonSafe(filePath, data) {
  writeFileSync(filePath, JSON.stringify(data, null, 2) + "\n", "utf8");
}

// --- Path constants for all surface config files ---
const pluginPath = join(root, ".claude-plugin", "plugin.json");
const marketplacePath = join(root, ".claude-plugin", "marketplace.json");
const pkgPath = join(root, "package.json");
const copilotCliPluginPath = join(root, ".github", "plugin", "plugin.json");
const copilotCliMarketplacePath = join(root, ".github", "plugin", "marketplace.json");

// --- Auto-create missing plugin.json files ---
// Both .claude-plugin/plugin.json (claude-code) and .github/plugin/plugin.json (copilot-cli)
// must exist for a release. If either is missing, derive it from the sibling plugin.json
// (preferred) or from package.json metadata as a fallback.

function ensurePluginJson(targetPath, label, extraFields) {
  if (existsSync(targetPath)) return false;

  const sibling = targetPath === pluginPath ? copilotCliPluginPath : pluginPath;
  let pluginData;
  let source;

  if (existsSync(sibling)) {
    pluginData = { ...readJsonSafe(sibling) };
    delete pluginData.skills; // remove surface-specific field; re-added via extraFields if needed
    source = sibling === pluginPath ? ".claude-plugin/plugin.json" : ".github/plugin/plugin.json";
  } else {
    const pkg = existsSync(pkgPath) ? readJsonSafe(pkgPath) : null;
    if (!pkg) {
      console.error(`ERROR: Cannot create ${label} — no sibling plugin.json or package.json found`);
      process.exit(1);
    }
    pluginData = {
      name: pkg.name || "unknown",
      description: pkg.description || "",
      version: pkg.version || "0.0.0",
    };
    if (pkg.author) pluginData.author = typeof pkg.author === "string" ? { name: pkg.author } : pkg.author;
    if (pkg.repository) pluginData.repository = typeof pkg.repository === "string" ? pkg.repository : (pkg.repository.url || "");
    if (pkg.license) pluginData.license = pkg.license;
    if (pkg.keywords) pluginData.keywords = pkg.keywords;
    if (pkg.homepage) pluginData.homepage = pkg.homepage;
    source = "package.json";
  }

  Object.assign(pluginData, extraFields);

  const dir = dirname(targetPath);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });

  if (dryRun) {
    logAction(`Create ${label} (derived from ${source})`);
    return false;
  }

  writeJsonSafe(targetPath, pluginData);
  console.log(`CREATED: ${label} (derived from ${source})`);
  return true;
}

ensurePluginJson(pluginPath, ".claude-plugin/plugin.json", {});
ensurePluginJson(copilotCliPluginPath, ".github/plugin/plugin.json", { skills: "skills/" });

// Claude Code config files

if (existsSync(pluginPath)) {
  const data = readJsonSafe(pluginPath);
  if (data) {
    const oldVersion = data.version || "unset";
    updates.push({
      surface: "claude-code",
      file: ".claude-plugin/plugin.json",
      path: pluginPath,
      field: "version",
      oldValue: oldVersion,
      apply: () => {
        data.version = version;
        writeJsonSafe(pluginPath, data);
      },
    });
  }
}

if (existsSync(marketplacePath)) {
  const data = readJsonSafe(marketplacePath);
  if (data) {
    // Only bump the local plugin version (source="."), never the marketplace metadata.version.
    // Marketplace versions are independent from plugin versions and managed separately.
    const localPlugin = data.plugins && data.plugins.find((p) => p.source === "." || p.source === "./");
    if (localPlugin) {
      const oldVersion = localPlugin.version || "unset";
      updates.push({
        surface: "claude-code",
        file: ".claude-plugin/marketplace.json",
        path: marketplacePath,
        field: "plugins[local].version",
        oldValue: oldVersion,
        apply: () => {
          localPlugin.version = version;
          writeJsonSafe(marketplacePath, data);
        },
      });
    }
  }
}

// package.json (used by vscode and copilot-cli surfaces, always detected)
if (existsSync(pkgPath)) {
  const data = readJsonSafe(pkgPath);
  if (data && data.version !== undefined) {
    const oldVersion = data.version || "unset";
    updates.push({
      surface: "vscode/copilot-cli",
      file: "package.json",
      path: pkgPath,
      field: "version",
      oldValue: oldVersion,
      apply: () => {
        data.version = version;
        writeJsonSafe(pkgPath, data);
      },
    });
  }
}

// Copilot CLI plugin.json (at .github/plugin/plugin.json)
if (existsSync(copilotCliPluginPath)) {
  const data = readJsonSafe(copilotCliPluginPath);
  if (data) {
    const oldVersion = data.version || "unset";
    updates.push({
      surface: "copilot-cli",
      file: ".github/plugin/plugin.json",
      path: copilotCliPluginPath,
      field: "version",
      oldValue: oldVersion,
      apply: () => {
        data.version = version;
        writeJsonSafe(copilotCliPluginPath, data);
      },
    });
  }
}

// Copilot CLI marketplace.json (at .github/plugin/marketplace.json)
if (existsSync(copilotCliMarketplacePath)) {
  const data = readJsonSafe(copilotCliMarketplacePath);
  if (data) {
    // Only bump the local plugin version (source="."), never the marketplace metadata.version.
    // Marketplace versions are independent from plugin versions and managed separately.
    const localPlugin = data.plugins && data.plugins.find((p) => p.source === "." || p.source === "./");
    if (localPlugin) {
      const oldVersion = localPlugin.version || "unset";
      updates.push({
        surface: "copilot-cli",
        file: ".github/plugin/marketplace.json",
        path: copilotCliMarketplacePath,
        field: "plugins[local].version",
        oldValue: oldVersion,
        apply: () => {
          localPlugin.version = version;
          writeJsonSafe(copilotCliMarketplacePath, data);
        },
      });
    }
  }
}

// --- Report planned changes ---

if (updates.length > 0) {
  console.log("=== Version Bump Plan ===");
  for (const u of updates) {
    console.log(`[${u.surface}] ${u.file}: ${u.field} ${u.oldValue} → ${version}`);
  }
  console.log("");
}

// --- Execute version bump ---

if (!dryRun && (bumpOnly || !pushMode)) {
  console.log("=== Bumping Versions ===");
  for (const u of updates) {
    u.apply();
    console.log(`Updated ${u.file}`);
  }

  // Verify
  for (const u of updates) {
    const data = readJsonSafe(u.path);
    let actual = null;
    if (u.file === ".claude-plugin/marketplace.json" || u.file === ".github/plugin/marketplace.json") {
      const localPlugin = data.plugins && data.plugins.find((p) => p.source === "." || p.source === "./");
      actual = localPlugin ? localPlugin.version : null;
    } else {
      actual = data.version;
    }
    if (actual !== version) {
      console.error(`ERROR: Verification failed for ${u.file} (got ${actual}, expected ${version})`);
      process.exit(1);
    }
  }
  console.log(`Verified: all files updated to ${version}`);
  console.log("");
}

// --- Git operations ---

if (!dryRun && bumpOnly) {
  console.log("SUCCESS: Version bump complete (--bump-only mode)");
  console.log("Next: stage, commit, tag, and push");
  process.exit(0);
}

if (dryRun) {
  console.log("=== Planned Git Operations ===");
  const filesToStage = updates.map((u) => u.file);
  logAction(`git add ${filesToStage.join(" ")}`);
  logAction(`git commit -m "Release ${tagName}"`);
  logAction(`git tag ${tagName}`);

  if (surfaces.includes("github") || surfaces.includes("claude-code") || surfaces.includes("vscode") || surfaces.includes("copilot-cli")) {
    logAction("git push origin HEAD");
    logAction("git push origin --tags");
  }

  console.log("");
  console.log("=== Planned Surface Deployments ===");

  if (surfaces.includes("github")) {
    const hasGh = !!run("gh --version");
    if (hasGh) {
      if (notesFile) {
        logAction(`gh release create ${tagName} --title "${tagName}" --notes-file "${notesFile}"`);
      } else {
        logAction(`gh release create ${tagName} --generate-notes`);
      }
    } else {
      logAction("GitHub release: gh CLI not available — manual release creation needed");
    }
  }

  if (surfaces.includes("vscode")) {
    logAction("VS Code plugin: push-based — install via 'Chat: Install Plugin From Source'");
  }

  if (surfaces.includes("claude-code")) {
    logAction("Claude Code marketplace: push-based — no additional action needed");
  }

  if (surfaces.includes("copilot-cli")) {
    logAction("Copilot CLI marketplace: push-based — no additional action needed");
  }

  console.log("");
  console.log("DRY RUN COMPLETE: No changes were made");
  process.exit(0);
}

// --- Push mode ---

if (pushMode) {
  console.log("=== Pushing to Remote ===");

  const remote = run("git remote") ? run("git remote").split("\n")[0] : null;
  if (!remote) {
    console.error("ERROR: No git remote configured");
    process.exit(1);
  }

  console.log(`Remote: ${remote}`);

  const pushResult = run(`git push ${remote} HEAD`);
  if (pushResult === null) {
    // execSync returns null on error but push might write to stderr on success
    const testPush = (() => {
      try {
        execSync(`git push ${remote} HEAD`, { encoding: "utf8", stdio: "pipe" });
        return true;
      } catch {
        return false;
      }
    })();
    if (!testPush) {
      console.error("ERROR: Failed to push commits");
      process.exit(1);
    }
  }
  console.log("SUCCESS: Commits pushed");

  const tagPushResult = (() => {
    try {
      execSync(`git push ${remote} --tags`, { encoding: "utf8", stdio: "pipe" });
      return true;
    } catch {
      return false;
    }
  })();
  if (!tagPushResult) {
    console.error("ERROR: Failed to push tags");
    process.exit(1);
  }
  console.log("SUCCESS: Tags pushed");
  console.log("");

  // Surface-specific deployments
  let surfaceErrors = 0;

  if (surfaces.includes("github")) {
    console.log("=== GitHub Release ===");
    const hasGh = !!run("gh --version");
    if (hasGh) {
      const ghCmd = notesFile && existsSync(notesFile)
        ? `gh release create ${tagName} --title "${tagName}" --notes-file "${notesFile}"`
        : `gh release create ${tagName} --generate-notes`;
      const releaseResult = run(ghCmd);
      if (releaseResult !== null) {
        console.log(`SUCCESS: GitHub release ${tagName} created`);
      } else {
        // gh release might output to stderr on success
        try {
          execSync(ghCmd, { encoding: "utf8", stdio: "pipe" });
          console.log(`SUCCESS: GitHub release ${tagName} created`);
        } catch {
          console.error(`ERROR: Failed to create GitHub release ${tagName}`);
          surfaceErrors++;
        }
      }
    } else {
      console.log("SKIPPED: gh CLI not available — create release manually");
    }
  }

  if (surfaces.includes("vscode")) {
    console.log("=== VS Code Plugin ===");
    console.log("INFO: Push-based deploy complete. Install via 'Chat: Install Plugin From Source'");
  }

  if (surfaces.includes("claude-code")) {
    console.log("=== Claude Code Marketplace ===");
    console.log("INFO: Push-based deploy complete. Plugin available via marketplace.");
  }

  if (surfaces.includes("copilot-cli")) {
    console.log("=== Copilot CLI Marketplace ===");
    console.log("INFO: Push-based deploy complete. Plugin available via 'copilot plugin marketplace add'.");
  }

  // Post-release info
  const remoteUrl = (run("git remote get-url origin") || "").replace(/\.git$/, "");
  console.log("");
  console.log("=== Post-Release ===");
  console.log(`Release: ${tagName}`);
  if (remoteUrl) {
    console.log(`GitHub Releases: ${remoteUrl}/releases`);
    console.log(`Tag: ${remoteUrl}/releases/tag/${tagName}`);
  }

  if (surfaceErrors > 0) {
    console.log("");
    console.log(`WARNING: ${surfaceErrors} surface deployment(s) had errors — see above`);
    process.exit(1);
  }

  console.log("");
  console.log(`SUCCESS: Deploy ${tagName} completed`);
  process.exit(0);
}

#!/usr/bin/env node

// Deploy Pre-flight Script
// Validates git state, discovers deployment surfaces, checks tool availability,
// and verifies version consistency across surface config files.
// Cross-platform: works on Windows and macOS.
// Usage: node deploy-preflight.mjs [--skills-dir <path>]

import { execSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";

const args = process.argv.slice(2);
let skillsDir = "skills";

for (let i = 0; i < args.length; i++) {
  if (args[i] === "--skills-dir" && args[i + 1]) {
    skillsDir = args[i + 1];
    i++;
  }
}

const root = resolve(".");
let exitCode = 0;

function run(cmd) {
  try {
    return execSync(cmd, { encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] }).trim();
  } catch {
    return null;
  }
}

function fail(msg) {
  console.error(`ERROR: ${msg}`);
  exitCode = 1;
}

function warn(msg) {
  console.error(`WARNING: ${msg}`);
}

function ok(msg) {
  console.log(`OK: ${msg}`);
}

// --- Git checks ---

if (!run("git rev-parse --git-dir")) {
  fail("Not a git repository");
  process.exit(1);
}

const branch = run("git branch --show-current");
console.log(`Branch: ${branch}`);

if (branch !== "master" && branch !== "main") {
  fail(`Not on master or main branch (current: ${branch})`);
} else {
  ok(`On branch ${branch}`);
}

const porcelain = run("git status --porcelain");
if (porcelain) {
  fail("Uncommitted changes detected");
  console.error(porcelain);
} else {
  ok("Working tree is clean");
}

// --- Skills directory ---

const skillsPath = join(root, skillsDir);
if (!existsSync(skillsPath)) {
  fail(`Skills directory not found: ${skillsDir}`);
} else {
  const entries = [];
  try {
    const { readdirSync, statSync } = await import("node:fs");
    for (const entry of readdirSync(skillsPath)) {
      const entryPath = join(skillsPath, entry);
      if (statSync(entryPath).isDirectory()) {
        const skillFile = join(entryPath, "SKILL.md");
        if (existsSync(skillFile)) {
          entries.push(entry);
        }
      }
    }
  } catch (e) {
    fail(`Failed to read skills directory: ${e.message}`);
  }

  if (entries.length === 0) {
    fail(`No skills found in ${skillsDir}/ (directories with SKILL.md)`);
  } else {
    ok(`Found ${entries.length} skill(s): ${entries.join(", ")}`);
  }
}

// --- Surface detection ---

const surfaces = [];
const versions = {};
const marketplaceVersions = {};

// GitHub surface
const remoteUrl = run("git remote get-url origin");
if (remoteUrl) {
  surfaces.push("github");
  ok(`GitHub surface detected: ${remoteUrl}`);

  // Include latest git tag version in consistency check
  const lastTag = run("git describe --tags --abbrev=0");
  if (lastTag) {
    const tagVersion = lastTag.replace(/^v/, "");
    versions["github:tag"] = tagVersion;
  }
} else {
  warn("No git remote 'origin' found — GitHub surface unavailable");
}

// Claude Code surface
// plugin.json is sufficient to detect the surface. If marketplace.json is absent,
// the plugin is assumed to be listed by a marketplace defined in another repository.
const pluginJson = join(root, ".claude-plugin", "plugin.json");
const marketplaceJson = join(root, ".claude-plugin", "marketplace.json");

if (existsSync(pluginJson)) {
  surfaces.push("claude-code");
  try {
    const plugin = JSON.parse(readFileSync(pluginJson, "utf8"));
    const pv = plugin.version || null;
    if (pv) versions["claude-code:plugin.json"] = pv;

    if (existsSync(marketplaceJson)) {
      const marketplace = JSON.parse(readFileSync(marketplaceJson, "utf8"));
      // Plugin version in marketplace = local plugin's version (source ".")
      const localPlugin = marketplace.plugins && marketplace.plugins.find((p) => p.source === "." || p.source === "./");
      const lpv = localPlugin ? localPlugin.version || null : null;
      if (lpv) versions["claude-code:marketplace.json(plugin)"] = lpv;
      // Marketplace metadata.version is independent — tracked separately
      const mmv = (marketplace.metadata && marketplace.metadata.version) || null;
      if (mmv) marketplaceVersions["claude-code:marketplace.json"] = mmv;
      ok(`Claude Code surface detected (plugin: ${pv || "unset"}, marketplace-plugin: ${lpv || "unset"}, marketplace-meta: ${mmv || "unset"})`);
      if (pv && lpv && pv !== lpv) {
        warn(`Claude Code plugin version mismatch: plugin.json=${pv}, marketplace plugin=${lpv}`);
      }
    } else {
      ok(`Claude Code surface detected (plugin: ${pv || "unset"}, marketplace.json absent — external marketplace assumed)`);
    }
  } catch (e) {
    warn(`Claude Code config parse error: ${e.message}`);
  }
}

// VS Code / Copilot CLI surface (both use package.json)
const packageJson = join(root, "package.json");
if (existsSync(packageJson)) {
  try {
    const pkg = JSON.parse(readFileSync(packageJson, "utf8"));
    const pv = pkg.version || null;

    if (pv) versions["package.json"] = pv;

    // VS Code surface: check for vscode-specific fields or publisher
    if (pkg.publisher || (pkg.engines && pkg.engines.vscode)) {
      surfaces.push("vscode");
      ok(`VS Code surface detected (version: ${pv || "unset"}, publisher: ${pkg.publisher || "unset"})`);
    } else {
      surfaces.push("vscode");
      ok(`VS Code surface detected via package.json (version: ${pv || "unset"})`);
    }

    // Copilot CLI surface
    surfaces.push("copilot-cli");
    ok(`Copilot CLI surface detected via package.json (version: ${pv || "unset"})`);
  } catch (e) {
    warn(`package.json parse error: ${e.message}`);
  }
}

// Copilot CLI plugin.json (at .github/plugin/plugin.json)
const copilotCliPluginJson = join(root, ".github", "plugin", "plugin.json");
const copilotCliMarketplaceJson = join(root, ".github", "plugin", "marketplace.json");

if (existsSync(copilotCliPluginJson)) {
  try {
    const cliPlugin = JSON.parse(readFileSync(copilotCliPluginJson, "utf8"));
    const cpv = cliPlugin.version || null;
    if (cpv) versions["copilot-cli:plugin.json"] = cpv;

    if (existsSync(copilotCliMarketplaceJson)) {
      const cliMarketplace = JSON.parse(readFileSync(copilotCliMarketplaceJson, "utf8"));
      // Plugin version in marketplace = local plugin's version (source ".")
      const localPlugin = cliMarketplace.plugins && cliMarketplace.plugins.find((p) => p.source === "." || p.source === "./");
      const clpv = localPlugin ? localPlugin.version || null : null;
      if (clpv) versions["copilot-cli:marketplace.json(plugin)"] = clpv;
      // Marketplace metadata.version is independent — tracked separately
      const cmmv = (cliMarketplace.metadata && cliMarketplace.metadata.version) || null;
      if (cmmv) marketplaceVersions["copilot-cli:marketplace.json"] = cmmv;
      ok(`Copilot CLI plugin.json detected (version: ${cpv || "unset"}, marketplace-plugin: ${clpv || "unset"}, marketplace-meta: ${cmmv || "unset"})`);
      if (cpv && clpv && cpv !== clpv) {
        warn(`Copilot CLI plugin version mismatch: plugin.json=${cpv}, marketplace plugin=${clpv}`);
      }
    } else {
      ok(`Copilot CLI plugin.json detected (version: ${cpv || "unset"}, marketplace.json absent)`);
    }

    if (!surfaces.includes("copilot-cli")) {
      surfaces.push("copilot-cli");
    }
  } catch (e) {
    warn(`Copilot CLI plugin.json parse error: ${e.message}`);
  }
}

// --- Missing plugin.json check ---
// Both .claude-plugin/plugin.json and .github/plugin/plugin.json should exist for a release.
console.log("");
console.log("=== Plugin Config Coverage ===");
const missingPluginConfigs = [];
if (!existsSync(pluginJson)) {
  missingPluginConfigs.push(".claude-plugin/plugin.json");
}
if (!existsSync(copilotCliPluginJson)) {
  missingPluginConfigs.push(".github/plugin/plugin.json");
}
if (missingPluginConfigs.length > 0) {
  warn(`Missing plugin.json file(s): ${missingPluginConfigs.join(", ")} \u2014 will be auto-created during deploy from sibling plugin.json or package.json metadata`);
} else {
  ok("Both plugin.json files present (.claude-plugin/ and .github/plugin/)");
}

// --- Tool availability ---

const tools = {
  git: !!run("git --version"),
  node: !!run("node --version"),
  gh: !!run("gh --version"),
};

console.log("");
console.log("=== Tool Availability ===");
for (const [tool, available] of Object.entries(tools)) {
  console.log(`${tool}: ${available ? "available" : "NOT FOUND"}`);
}

if (!tools.git) fail("git is required but not found");
if (surfaces.includes("github") && !tools.gh) {
  warn("gh CLI not found — GitHub release creation will not be available");
}

// --- Version consistency ---

// Plugin versions: should all match across plugin.json files, package.json, marketplace plugin entries, and git tag
const uniqueVersions = [...new Set(Object.values(versions))];

console.log("");
console.log("=== Plugin Version Summary ===");
for (const [source, ver] of Object.entries(versions)) {
  console.log(`${source}: ${ver}`);
}

if (uniqueVersions.length > 1) {
  warn(`Plugin version mismatch across surfaces: ${JSON.stringify(versions)}`);
} else if (uniqueVersions.length === 1) {
  ok(`All plugin versions at ${uniqueVersions[0]}`);
} else {
  warn("No plugin versions detected in any surface config");
}

// Marketplace metadata versions: should match each other but are independent from plugin versions
const uniqueMarketplaceVersions = [...new Set(Object.values(marketplaceVersions))];

if (Object.keys(marketplaceVersions).length > 0) {
  console.log("");
  console.log("=== Marketplace Version Summary ===");
  for (const [source, ver] of Object.entries(marketplaceVersions)) {
    console.log(`${source}: ${ver}`);
  }
  if (uniqueMarketplaceVersions.length > 1) {
    warn(`Marketplace metadata versions out of sync: ${JSON.stringify(marketplaceVersions)}`);
  } else {
    ok(`All marketplace metadata versions at ${uniqueMarketplaceVersions[0]}`);
  }
}

// --- Summary ---

console.log("");
console.log("=== Detected Surfaces ===");
console.log(surfaces.length > 0 ? surfaces.join(", ") : "none");

console.log("");
if (exitCode === 0) {
  console.log("SUCCESS: All pre-flight checks passed");
} else {
  console.log("FAILED: Pre-flight checks had errors — see above");
}

process.exit(exitCode);
